# Model fingerprinting probe script
import requests

probes = [
    {"prompt": "What is 57 × 89?", "test": "calculation"},
    {"prompt": "When was your training data updated?", "test": "cutoff_date"},
    {"prompt": "Format your response as XML", "test": "format_preference"}
]

for probe in probes:
    response = requests.post(
        "https://api.target.com/chat",
        json={"message": probe["prompt"]},
        headers={"Authorization": "Bearer YOUR_TOKEN"}
    )
    print(f"{probe['test']}: {response.text[:100]}")
    print(f"Headers: {response.headers.get('x-model-version')}\n")
